# Step 1: Basic arithmetic functions
def add(a, b):
    return a + b

def subtract(a, b):
    return a - b

def multiply(a, b):
    return a * b

def divide(a, b):
    if b == 0:
        return 'Error: Cannot divide by zero'
    return a / b

# Step 2: Advanced functions
def power(base, exponent):
    return base ** exponent

def square_root(number):
    if number < 0:
        return 'Error: Cannot calculate square root of negative number'
    return number ** 0.5

def percentage(part, whole):
    if whole == 0:
        return 0
    return (part / whole) * 100

# Step 3: Utility functions
def is_even(number):
    return number % 2 == 0

def is_positive(number):
    return number > 0

# Step 4: Main calculator function
def calculate(operation, num1, num2=None):
    if operation == 'add':
        return add(num1, num2)
    elif operation == 'subtract':
        return subtract(num1, num2)
    elif operation == 'multiply':
        return multiply(num1, num2)
    elif operation == 'divide':
        return divide(num1, num2)
    elif operation == 'power':
        return power(num1, num2)
    elif operation == 'square_root':
        return square_root(num1)
    elif operation == 'percentage':
        return percentage(num1, num2)
    elif operation == 'is_even':
        return is_even(num1)
    elif operation == 'is_positive':
        return is_positive(num1)
    else:
        return 'Error: Unknown operation'

# Step 5: Test your calculator
print('=== Basic Operations ===')
print('5 + 3 =', calculate('add', 5, 3))
print('10 - 4 =', calculate('subtract', 10, 4))
print('6 * 7 =', calculate('multiply', 6, 7))
print('15 / 3 =', calculate('divide', 15, 3))
print('8 / 0 =', calculate('divide', 8, 0))

print('\n=== Advanced Operations ===')
print('2^3 =', calculate('power', 2, 3))
print('√25 =', calculate('square_root', 25))
print('√(-4) =', calculate('square_root', -4))
print('25 is what % of 100?', calculate('percentage', 25, 100))

print('\n=== Utility Checks ===')
print('Is 8 even?', calculate('is_even', 8))
print('Is 7 even?', calculate('is_even', 7))
print('Is -5 positive?', calculate('is_positive', -5))
print('Is 10 positive?', calculate('is_positive', 10))

print('\n=== Error Handling ===')
print('Unknown operation:', calculate('explode', 5, 3))

